#!/usr/bin/env node
// HS86E - RSG-ENG-UI-007 Cultural Games UI Architecture - Release script
// ASCII-only, idempotent. Embeds 5 files (1 rewritten page + 4 game plates)
// as base64 and writes them byte-exact relative to the repo root.
// Run from the repo root (the folder that contains hs86e-tickets/):
//   node hs86e-games-ui-release.mjs
// Safe to re-run: every target is overwritten with the embedded bytes.

import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';

const repoRoot = process.cwd();
const files = [
  { p: "hs86e-tickets/src/app/games/page.tsx", data: "" },
  { p: "hs86e-tickets/public/images/games/mancala.jpg", data: "" },
  { p: "hs86e-tickets/public/images/games/ludo.jpg", data: "" },
  { p: "hs86e-tickets/public/images/games/checkers.jpg", data: "" },
  { p: "hs86e-tickets/public/images/games/whot.jpg", data: "" },
];

let written = 0;
for (const f of files) {
  const target = join(repoRoot, f.p);
  mkdirSync(dirname(target), { recursive: true });
  writeFileSync(target, Buffer.from(f.data, 'base64'));
  console.log('wrote', f.p);
  written++;
}
console.log('RSG-ENG-UI-007 release complete:', written, 'files written.');
console.log('Next: cd hs86e-tickets && npx tsc --noEmit && npm run build');
